Let LYa := PMB.ly_as0 L C LY.

Theorem long_c : PMB.opnew_spec L ar HI -> forall (fx : FPState) R0 M0 model0 K LB FF LK0 Aw0 cr ois os sp r c0 n p0 b R2 M2 model2 LK2 Aw2 (l : list Z),
    PMBIS.pre L ar HI R0 M0 model0 K LB FF LK0 Aw0 cr ois os sp r (PM.VLong c0 n p0) b ->
    PEBCIS2.kont_c L ar HI R0 M0 model0 K LB FF LK0 Aw0 cr ois sp r (PM.VLong c0 n p0) b l ->
    Z.of_nat (length l) = n -> L5.bytes_at RSEGS M0 p0 l ->
    PMBIS.mid2 L ar HI R0 M0 model0 LB FF LK0 Aw0 cr ois os sp (PM.VLong c0 n p0) b R2 M2 model2 LK2 Aw2 ->
    srealizes RSEGS SCFG (PMSPA.cfg RSEGS (fx:=fx) R2 0xab41c M2 model2) K.
Proof.
